  `requirement` longtext COLLATE utf8mb4_unicode_ci,
  `remarks` longtext COLLATE utf8mb4_unicode_ci,
  `is_counterfeit` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_apd_announcement_id` (`announcement_id`),
  KEY `idx_apd_sequence_no` (`sequence_no`),
  KEY `idx_apd_product_name` (`product_name`),
  KEY `idx_apd_is_counterfeit` (`is_counterfeit`),
  CONSTRAINT `fk_announcement_product_details_announcement` FOREIGN KEY (`announcement_id`) REFERENCES `announcements` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1175 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
