DROP TABLE IF EXISTS `announcement_staging_batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `announcement_staging_batches` (
  `id` int NOT NULL AUTO_INCREMENT,
  `source_sequence` int DEFAULT NULL,
  `source_json_file` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_detail_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_page` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `announcement_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `publish_date` date DEFAULT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci,
  `inspection_unit` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_count` int DEFAULT '0',
  `attachment_count` int DEFAULT '0',
  `parsed_detail_count` int DEFAULT '0',
  `counterfeit_count` int DEFAULT '0',
  `primary_attachment_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primary_attachment_path` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cosmetics',
  `announcement_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sampling',
  `raw_payload` longtext COLLATE utf8mb4_unicode_ci,
  `status` enum('pending','confirmed') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `published_announcement_id` int DEFAULT NULL,
  `published_supervision_id` int DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_staging_source_json_file` (`source_json_file`),
  KEY `idx_staging_status_publish_date` (`status`,`publish_date`),
  KEY `idx_staging_announcement_no` (`announcement_no`),
  KEY `idx_staging_published_announcement` (`published_announcement_id`),
  KEY `idx_staging_product_type` (`product_type`),
  KEY `idx_staging_announcement_type` (`announcement_type`),
  KEY `idx_staging_published_supervision` (`published_supervision_id`),
  CONSTRAINT `fk_staging_published_announcement` FOREIGN KEY (`published_announcement_id`) REFERENCES `announcements` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=170 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
